"use client"

import { useEffect, useId, useMemo, useRef, useState } from "react"

export type Currency = { code: string; name: string; symbol: string; perUsd: number; decimals?: number }

export type OdometerCurrencyConverterProps = {
  /** Currencies on offer, each priced as units per 1 USD. */
  currencies?: Currency[]
  from?: string
  to?: string
  /** Starting amount in the `from` currency. */
  amount?: number
  /** Largest amount accepted. */
  max?: number
  /** Quick-pick amounts. */
  presets?: number[]
  /** Fires when the rate is locked. */
  onLock?: (q: { from: string; to: string; amount: number; converted: number; rate: number }) => void
  className?: string
}

