// #region money
/** Units of `to` for one unit of `from`, from per-USD prices. */
export function crossRate(fromPerUsd: number, toPerUsd: number) {
  return fromPerUsd > 0 ? toPerUsd / fromPerUsd : 0
}

export function roundTo(n: number, decimals: number) {
  const f = Math.pow(10, decimals)
  return Math.round(n * f) / f
}

/** Group with commas, fixed decimals: 1234.5 -> "1,234.50". */
export function formatAmount(n: number, decimals: number) {
  const [int, frac] = Math.abs(roundTo(n, decimals)).toFixed(decimals).split(".")
  const grouped = int.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
  return (n < 0 ? "-" : "") + grouped + (frac ? "." + frac : "")
}

/**
 * Keep what a person types to digits, one dot and `decimals` places, and drop
 * grouping commas. Returns the cleaned text.
 */
export function cleanInput(raw: string, decimals: number) {
  let s = raw.replace(/,/g, "").replace(/[^\d.]/g, "")
  const dot = s.indexOf(".")
  if (dot > -1) s = s.slice(0, dot + 1) + s.slice(dot + 1).replace(/\./g, "")
  if (decimals === 0) s = s.replace(/\..*$/, "")
  else if (dot > -1) s = s.slice(0, dot + 1 + decimals)
  s = s.replace(/^0+(?=\d)/, "")
  return s
}

/** Show typed text with grouping, keeping a trailing dot or zeros the person is typing. */
export function groupTyped(s: string) {
  if (!s) return ""
  const [int, frac] = s.split(".")
  const g = (int || "0").replace(/\B(?=(\d{3})+(?!\d))/g, ",")
  return frac === undefined ? g : g + "." + frac
}

/** A smooth 30-point history that ends on `rate`, the same every time for a pair. */
export function history(pair: string, rate: number, points = 30) {
  let seed = 0
  for (let i = 0; i < pair.length; i++) seed = (seed * 31 + pair.charCodeAt(i)) >>> 0
  const rnd = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0
    return seed / 4294967296
  }
  const out = [rate]
  let v = rate
  for (let i = 1; i < points; i++) {
    v = v * (1 + (rnd() - 0.5) * 0.012)
    out.unshift(v)
  }
  return out
}
// #endregion

function Odometer({ text, label }: { text: string; label: string }) {
  const chars = text.split("")
  return (
    <span className="occ-odo" aria-label={label} role="text">
      {chars.map((c, i) => {
        // Key from the right so the ones column stays the ones column as the number grows.
        const k = chars.length - i
        if (!/\d/.test(c))
          return (
            <span key={"s" + k} className="occ-sep" aria-hidden="true">
              {c}
            </span>
          )
        return (
          <span key={"d" + k} className="occ-col" aria-hidden="true" style={{ ["--occ-d" as string]: k }}>
            <span style={{ transform: "translateY(" + -+c * 1.1 + "em)" }}>
              {"0123456789".split("").map((d) => (
                <b key={d}>{d}</b>
              ))}
            </span>
          </span>
        )
      })}
    </span>
  )
}

function Picker({
  value,
  options,
  onPick,
  label,
}: {
  value: Currency
  options: Currency[]
  onPick: (code: string) => void
  label: string
}) {
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const btn = useRef(null as HTMLButtonElement | null)
  const list = useRef(null as HTMLUListElement | null)
  const id = useId()

  useEffect(() => {
    if (!open) return
    setActive(Math.max(0, options.findIndex((o) => o.code === value.code)))
    list.current?.focus()
    const away = (e: PointerEvent) => {
      if (!(e.target instanceof Node)) return
      if (!list.current?.contains(e.target) && !btn.current?.contains(e.target)) setOpen(false)
    }
    document.addEventListener("pointerdown", away)
    return () => document.removeEventListener("pointerdown", away)
  }, [open, options, value.code])

  useEffect(() => {
    if (open) list.current?.querySelector("[data-active=true]")?.scrollIntoView({ block: "nearest" })
  }, [active, open])

  const choose = (i: number) => {
    onPick(options[i].code)
    setOpen(false)
    btn.current?.focus()
  }

  return (
    <div className="occ-pick">
      <button
        ref={btn}
        type="button"
        className="occ-cur"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={id}
        aria-label={label + ": " + value.name}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault()
            setOpen(true)
          }
        }}
      >
        <span className="occ-coin" data-long={value.symbol.length > 1}>
          {value.symbol}
        </span>
        {value.code}
        <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true">
          <path d="M3 4.5l3 3 3-3" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>
      {open && (
        <ul
          ref={list}
          id={id}
          className="occ-list"
          role="listbox"
          tabIndex={-1}
          aria-label={label}
          aria-activedescendant={id + "-" + active}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") setActive((a) => (a + 1) % options.length)
            else if (e.key === "ArrowUp") setActive((a) => (a - 1 + options.length) % options.length)
            else if (e.key === "Home") setActive(0)
            else if (e.key === "End") setActive(options.length - 1)
            else if (e.key === "Enter" || e.key === " ") choose(active)
            else if (e.key === "Escape" || e.key === "Tab") {
              setOpen(false)
              if (e.key === "Escape") btn.current?.focus()
              return
            } else if (/^[a-z]$/i.test(e.key)) {
              const n = options.findIndex((o, i) => i > active && o.code.startsWith(e.key.toUpperCase()))
              const f = n > -1 ? n : options.findIndex((o) => o.code.startsWith(e.key.toUpperCase()))
              if (f > -1) setActive(f)
            } else return
            e.preventDefault()
          }}
        >
          {options.map((o, i) => (
            <li
              key={o.code}
              id={id + "-" + i}
              role="option"
              aria-selected={o.code === value.code}
              data-active={i === active}
              className="occ-opt"
              style={{ ["--occ-d" as string]: i }}
              onPointerEnter={() => setActive(i)}
              onClick={() => choose(i)}
            >
              <span className="occ-coin" data-long={o.symbol.length > 1}>
                {o.symbol}
              </span>
              <span>
                {o.code}
                <small>{o.name}</small>
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

export default function OdometerCurrencyConverter({
  currencies = DEFAULT_CURRENCIES,
  from: from0 = "USD",
  to: to0 = "EUR",
  amount = 1000,
  max = 1_000_000,
  presets = [100, 500, 1000, 5000],
  onLock,
  className = "",
}: OdometerCurrencyConverterProps) {
  const find = (c: string) => currencies.find((x) => x.code === c) || currencies[0]
  const [fromCode, setFrom] = useState(from0)
  const [toCode, setTo] = useState(to0)
  const [text, setText] = useState(String(amount))
  const [spin, setSpin] = useState(0)
  const [swapTick, setSwapTick] = useState(0)
  const [lockedAt, setLockedAt] = useState(0)
  const [now, setNow] = useState(0)
  const [shown, setShown] = useState(false)
  const uid = useId()

  const from = find(fromCode)
  const to = find(toCode)
  const fromDec = from.decimals ?? 2
  const toDec = to.decimals ?? 2
  const value = parseFloat(text) || 0
  const tooBig = value > max
  const rate = crossRate(from.perUsd, to.perUsd)
  const converted = tooBig ? 0 : roundTo(value * rate, toDec)
  const hist = useMemo(() => history(from.code + to.code, rate), [from.code, to.code, rate])
  const change = hist[0] ? (rate - hist[0]) / hist[0] : 0

  // Roll in from zero once mounted.
  useEffect(() => {
    const t = setTimeout(() => setShown(true), 250)
    return () => clearTimeout(t)
  }, [])

  // The lock counts down for 30 s, then expires.
  useEffect(() => {
    if (!lockedAt) return
    setNow(Date.now())
    const t = setInterval(() => {
      const n = Date.now()
      setNow(n)
      if (n - lockedAt >= 30000) setLockedAt(0)
    }, 250)
    return () => clearInterval(t)
  }, [lockedAt])

  // Changing the quote releases the lock.
  useEffect(() => setLockedAt(0), [fromCode, toCode, text])

  const swap = () => {
    setFrom(toCode)
    setTo(fromCode)
    setSpin((s) => s + 180)
    setSwapTick((t) => t + 1)
    const nd = to.decimals ?? 2
    if (!tooBig && value) setText(cleanInput(String(converted), nd))
  }

  const pick = (side: "from" | "to") => (code: string) => {
    if (side === "from") {
      if (code === toCode) setTo(fromCode)
      setFrom(code)
      setText((t) => cleanInput(t, find(code).decimals ?? 2))
    } else {
      if (code === fromCode) setFrom(toCode)
      setTo(code)
    }
  }

  // Path for the sparkline in a 200 x 38 box.
  const lo = Math.min(...hist)
  const hi = Math.max(...hist)
  const pts = hist.map((v, i) => [(i / (hist.length - 1)) * 200, 34 - ((v - lo) / (hi - lo || 1)) * 30])
  const line = pts.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" ")
  const left = lockedAt ? Math.max(0, 30 - Math.floor((now - lockedAt) / 1000)) : 0
  const outText = formatAmount(shown ? converted : 0, toDec)
  const errId = uid + "-err"

  return (
    <section className={"occ-root " + className} aria-label="Currency converter">
      <style>{CSS}</style>
      <div className="occ-head">
        <h3 className="occ-h">
          Send <em>abroad</em>
        </h3>
        <span className="occ-live">
          <i aria-hidden="true" />
          Mid-market rate
        </span>
      </div>

      <div className="occ-panel" data-invalid={tooBig} data-swap={swapTick > 0} key={"f" + swapTick}>
        <label className="occ-label" htmlFor={uid + "-amt"}>
          <span>You send</span>
          {tooBig && (
            <span data-tone="bad" id={errId} role="alert">
              Max {formatAmount(max, 0)} {from.code}
            </span>
          )}
        </label>
        <div className="occ-row">
          <span className="occ-amt-wrap">
            <span className="occ-sym" aria-hidden="true">
              {from.symbol}
            </span>
            <input
              id={uid + "-amt"}
              className="occ-input"
              inputMode="decimal"
              autoComplete="off"
              placeholder="0"
              value={groupTyped(text)}
              aria-invalid={tooBig}
              aria-describedby={tooBig ? errId : undefined}
              onChange={(e) => setText(cleanInput(e.target.value, fromDec))}
              onKeyDown={(e) => {
                if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return
                e.preventDefault()
                const step = e.shiftKey ? 100 : 10
                setText(String(Math.max(0, roundTo(value + (e.key === "ArrowUp" ? step : -step), fromDec))))
              }}
            />
          </span>
          <Picker value={from} options={currencies} onPick={pick("from")} label="Currency you send" />
        </div>
      </div>

      <div className="occ-mid">
        <span className="occ-rate" aria-live="polite">
          1 {from.code} = <b>{formatAmount(rate, rate < 10 ? 4 : 2)}</b> {to.code}
        </span>
        <button type="button" className="occ-swap" onClick={swap} aria-label={"Swap " + from.code + " and " + to.code}>
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true" style={{ transform: "rotate(" + spin + "deg)" }}>
            <path d="M6 3v13m0 0-3-3m3 3 3-3M14 17V4m0 0-3 3m3-3 3 3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
      </div>

      <div className="occ-panel" data-swap={swapTick > 0} key={"t" + swapTick}>
        <div className="occ-label">
          <span>They receive</span>
        </div>
        <div className="occ-row">
          <span className="occ-amt-wrap">
            <span className="occ-sym" aria-hidden="true">
              {to.symbol}
            </span>
            <Odometer text={outText} label={formatAmount(converted, toDec) + " " + to.name} />
          </span>
          <Picker value={to} options={currencies} onPick={pick("to")} label="Currency they receive" />
        </div>
      </div>

      <div className="occ-trend">
        <svg viewBox="0 0 200 38" preserveAspectRatio="none" aria-hidden="true" key={from.code + to.code}>
          <defs>
            <linearGradient id={uid + "-g"} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stopColor="#b8893a" stopOpacity=".42" />
              <stop offset="1" stopColor="#b8893a" stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d={line + " L200 38 L0 38 Z"} fill={"url(#" + uid + "-g)"} />
          <path className="occ-line" d={line} fill="none" stroke="#10362b" strokeWidth="1.6" strokeLinejoin="round" />
          <circle cx={pts[pts.length - 1][0]} cy={pts[pts.length - 1][1]} r="3" fill="#b8893a" stroke="#f5f0e4" strokeWidth="1.5" />
        </svg>
        <span className="occ-delta">
          <b data-up={change >= 0}>
            {change >= 0 ? "+" : "−"}
            {Math.abs(change * 100).toFixed(2)}%
          </b>
          past 30 days
        </span>
      </div>

      <div className="occ-chips" role="group" aria-label="Quick amounts">
        {presets.map((p) => (
          <button key={p} type="button" className="occ-chip" aria-pressed={value === p} onClick={() => setText(String(p))}>
            {from.symbol}
            {formatAmount(p, 0)}
          </button>
        ))}
      </div>

      <button
        type="button"
        className="occ-cta"
        data-locked={!!lockedAt}
        disabled={!value || tooBig}
        onClick={() => {
          if (lockedAt) return
          setLockedAt(Date.now())
          onLock?.({ from: from.code, to: to.code, amount: value, converted, rate })
        }}
      >
        {lockedAt ? (
          <>
            <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true">
              <circle cx="10" cy="10" r="8" fill="none" stroke="rgba(43,28,5,.25)" strokeWidth="2.2" />
              <circle className="occ-ring" cx="10" cy="10" r="8" fill="none" stroke="#2b1c05" strokeWidth="2.2" strokeLinecap="round" pathLength={1} strokeDasharray="1" strokeDashoffset={1 - left / 30} />
            </svg>
            Rate locked · {left}s
          </>
        ) : (
          <>
            Lock this rate
            <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
              <path d="M3.5 9h11m0 0-4-4m4 4-4 4" stroke="#e3c27a" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </>
        )}
      </button>
      <span className="occ-sr" aria-live="polite">
        {lockedAt ? "Rate locked for 30 seconds" : ""}
      </span>
    </section>
  )
}
